def compute(vars):
    securities = vars["v1"]
    exercise_price = vars["v2"]
    value_usd = securities * exercise_price
    value_millions = value_usd / 1000000
    return {
        "value": value_millions,
        "trace": {
            "securities": securities,
            "weighted_average_exercise_price": exercise_price,
            "value_usd": value_usd,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "USD"
            }
        }
    }
